#!/usr/bin/env bash
# Derives .github/workflows/ominax-ci.yml from upstream's ci.yml for the
# t3-learn fork. Upstream runs CI on Blacksmith runners, which the fork has no
# account for, so their jobs would queue forever. Editing ci.yml itself would
# conflict with every upstream sync, so the fork keeps ci.yml untouched (and
# disabled) and runs this generated copy on GitHub-hosted runners instead.
#
# Rerun after every upstream sync and commit the result if it changed:
#   bash .github/scripts/ominax-ci.sh
# Lint fails while the committed copy differs from this script's output.
#
# ci-changes.cjs runs the macOS job only when ci.yml (not this script or its
# output) changes, so a PR that changes the macOS runner mapping skips it.
# Prove such a change with `gh workflow run ominax-ci.yml --ref <branch>` and
# a passing Mobile Native Static Analysis job before merging.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
source_file="$root/.github/workflows/ci.yml"
output_file="$root/.github/workflows/ominax-ci.yml"

# blacksmith-6vcpu-macos-26 is Apple silicon; GitHub's macos-26 is arm64 too.
# Lint always runs and Check already needs it, so the drift guard lives there.
# Test Web runs on one 8 vCPU runner upstream. Browser test files share one
# Chromium page, and on a slower 4 vCPU runner the heaviest file previews then
# miss their 15s test and waitFor windows, so the fork splits Test Web across
# four runners. Upstream's PDF reload test still takes 13-15s there, so tests
# get 30s. vp run passes a `--` through, so the flags follow the script.
transform='
s/^name: CI$/name: OminaX CI/
s/^( *)runs-on: blacksmith-[0-9]+vcpu-ubuntu-2404$/\1runs-on: ubuntu-24.04/
s/^( *)runs-on: blacksmith-[0-9]+vcpu-macos-26$/\1runs-on: macos-26/
/^  test_web:$/,/^  [a-z_]+:$/{
  s/^(    name: Test Web)$/\1 ${{ matrix.shard }}/
  /^    runs-on: ubuntu-24.04$/a\
    strategy:\
      fail-fast: false\
      matrix:\
        shard: [1, 2, 3, 4]
  s/^(        run: vp run --filter @t3tools\/web test)$/\1 --shard ${{ matrix.shard }}\/${{ strategy.job-total }} --testTimeout=30000/
}
# The scripted learner (scripts/learner-e2e.ts) drives the web build this job
# just made against a source server on Replay, so a server-only PR runs it too
# and needs the Chromium the boot check installs.
/^  build:$/,/^  [a-z_]+:$/{
  s/^    timeout-minutes: 10$/    timeout-minutes: 15/
  /^      - name: Resolve Playwright version$/,/^      - name: Boot the built web client$/{
    s/needs\.changes\.outputs\.test_web != '\''false'\''/(& || needs.changes.outputs.test_server != '\''false'\'')/
  }
  /^        run: node apps\/web\/scripts\/verify-built-boot\.ts$/a\
\
      - name: Run the scripted learner\
        if: ${{ !cancelled() && steps.build.outcome == '\''success'\'' && (needs.changes.outputs.test_web != '\''false'\'' || needs.changes.outputs.test_server != '\''false'\'') }}\
        timeout-minutes: 8\
        run: node scripts/learner-e2e.ts --skip-build --out "$RUNNER_TEMP/learner-e2e"\
\
      - name: Upload scripted learner results\
        if: failure()\
        uses: actions/upload-artifact@v7\
        with:\
          name: learner-e2e\
          path: ${{ runner.temp }}/learner-e2e
}
/^      - name: Reject repository-owned PR assets$/i\
      - name: Require ominax-ci.yml to match ci.yml\
        run: bash .github/scripts/ominax-ci.sh && git diff --exit-code -- .github/workflows/ominax-ci.yml\

'
# workflow_dispatch runs every job on demand: ci-changes has no base commit to
# diff against and fails open. A second copy of the key would invalidate the
# workflow, so add it only while upstream has none.
if ! grep -q '^  workflow_dispatch:' "$source_file"; then
  transform+='
s/^on:$/on:\
  workflow_dispatch:/
'
fi

generated="$(
  printf '%s\n' \
    "# Generated by .github/scripts/ominax-ci.sh from .github/workflows/ci.yml." \
    "# Do not edit by hand. Regenerate with: bash .github/scripts/ominax-ci.sh" \
    ""
  sed -E "$transform" "$source_file"
)"

# Fail loudly when upstream changes a line the transform depends on, rather
# than writing a workflow that queues on Blacksmith or shadows upstream's name.
fail() {
  echo "ominax-ci.sh: $*; update the transform for the new ci.yml." >&2
  exit 1
}
count() { grep -c "$1" <<<"$generated" || true; }
[[ $(count '^name: OminaX CI$') -eq 1 ]] || fail "workflow name not rewritten"
[[ $(count '^  workflow_dispatch:') -eq 1 ]] || fail "expected exactly one workflow_dispatch trigger"
[[ $(count '^    name: Check$') -eq 1 ]] || fail "aggregate Check job missing"
[[ $(count '^      - name: Require ominax-ci.yml to match ci.yml$') -eq 1 ]] ||
  fail "drift guard not inserted into Lint"
[[ $(count '^    name: Test Web \${{ matrix.shard }}$') -eq 1 ]] ||
  fail "Test Web shards not applied"
[[ $(count '^        run: vp run --filter @t3tools/web test --shard ') -eq 1 ]] ||
  fail "Test Web shard flag not applied"
[[ $(count '^      - name: Run the scripted learner$') -eq 1 ]] ||
  fail "scripted learner step not appended to Build"
[[ $(count "test_web != 'false' || needs.changes.outputs.test_server != 'false'") -eq 5 ]] ||
  fail "Chromium steps not widened for server-only changes"
# Any runner label, including one set through a matrix or an input.
if grep -nE 'blacksmith-[0-9]+vcpu-' <<<"$generated" >&2; then
  fail "unmapped Blacksmith runner"
fi

printf '%s\n' "$generated" > "$output_file"
